### Iteration 1: Basic Matrix Multiplication Kernel
We'll implement a naive matrix multiplication kernel where each thread computes one output element. This will serve as our baseline for optimization.

```python
# r09_i01_cuda_kernel.py
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int n) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < n && col < n) {
        float sum = 0.0f;
        for (int k = 0; k < n; k++) {
            sum += A[row * n + k] * B[k * n + col];
        }
        C[row * n + col] = sum;
    }
}

torch::Tensor matmul_forward_cuda(torch::Tensor A, torch::Tensor B) {
    int n = A.size(0);
    auto C = torch::zeros_like(A);

    dim3 threadsPerBlock(16, 16);
    dim3 numBlocks((n + threadsPerBlock.x - 1) / threadsPerBlock.x, 
                   (n + threadsPerBlock.y - 1) / threadsPerBlock.y);

    matmul_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                 B.data_ptr<float>(), 
                                                 C.data_ptr<float>(), 
                                                 n);
    return C;
}
"""

cpp_source = "torch::Tensor matmul_forward_cuda(torch::Tensor A, torch::Tensor B);"

matmul_extension = load_inline(
    name='matmul_extension',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['matmul_forward_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x1, x2):
        return matmul_extension.matmul_forward_cuda(x1, x2)
