### Iteration 2: Shared Memory Optimization
Now let's optimize by using shared memory to reduce global memory accesses. We'll implement tiled matrix multiplication where we load blocks of matrices A and B into shared memory.

```python
# r09_i02_cuda_kernel.py
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int n) {
    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < n; tile += TILE_SIZE) {
        // Load tile of A into shared memory
        if (row < n && threadIdx.x + tile < n) {
            As[threadIdx.y][threadIdx.x] = A[row * n + threadIdx.x + tile];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        if (threadIdx.y + tile < n && col < n) {
            Bs[threadIdx.y][threadIdx.x] = B[(threadIdx.y + tile) * n + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial product
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < n && col < n) {
        C[row * n + col] = sum;
    }
}

torch::Tensor matmul_forward_cuda(torch::Tensor A, torch::Tensor B) {
    int n = A.size(0);
    auto C = torch::zeros_like(A);

    dim3 threadsPerBlock(TILE_SIZE, TILE_SIZE);
    dim3 numBlocks((n + TILE_SIZE - 1) / TILE_SIZE, 
                   (n + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                 B.data_ptr<float>(), 
                                                 C.data_ptr<float>(), 
                                                 n);
    return C;
}
"""

