### Iteration 3: Register Tiling and Loop Unrolling
Now let's further optimize by using register tiling and loop unrolling. Each thread will compute a 4x4 block of the output matrix to increase arithmetic intensity and reduce shared memory accesses.

```python
# r09_i03_cuda_kernel.py
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 8

__global__ void matmul_kernel(const float* A, const float* B, float* C, int n) {
    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block indices
    int bx = blockIdx.x * TILE_SIZE;
    int by = blockIdx.y * TILE_SIZE;

    // Each thread computes a 4x4 block of C
    float c[4][4] = {{0.0f}};

    for (int t = 0; t < n; t += TILE_SIZE) {
        // Load tile of A into shared memory
        for (int i = 0; i < 4; i++) {
            int row = by + ty * 4 + i;
            int col = t + tx * 4;
            if (row < n && col < n) {
                As[ty * 4 + i][tx * 4] = A[row * n + col];
                As[ty * 4 + i][tx * 4 + 1] = A[row * n + col + 1];
                As[ty * 4 + i][tx * 4 + 2] = A[row * n + col + 2];
                As[ty * 4 + i][tx * 4 + 3] = A[row * n + col + 3];
            } else {
                As[ty * 4 + i][tx * 4] = 0.0f;
                As[ty * 4 + i][tx * 4 + 1] = 0.0f;
                As[ty * 4 + i][tx * 4 + 2] = 0.0f;
                As[ty * 4 + i][tx * 4 + 3] = 0.0f;
            }
        }

        // Load tile of B into shared memory (transposed)
        for (int i = 0; i < 4; i++) {
            int row = t + ty * 4 + i;
            int col = bx + tx * 4;
            if (row < n && col < n) {
                Bs[tx * 4][ty * 4 + i] = B[row * n + col];
                Bs[tx * 4 + 1][ty * 4 + i] = B[row * n + col + 1];
                Bs[tx * 4 + 2][ty * 4 + i] = B[row * n + col + 2];
                Bs[tx * 4 + 3][ty * 4 + i] = B[row * n + col + 3];
            } else {
                Bs[tx * 4][ty * 4 + i] = 0.0f;
                Bs[tx * 4 + 1][ty * 4 + i] = 0.0f;
                Bs[tx * 4 + 2][ty * 4 + i] = 0.0f;
                Bs[tx * 4 + 3][ty * 4 + i] = 0.0f;
            }
        }

        __syncthreads();

        // Compute 4x4 block using register tiling
        for (int k = 0; k < TILE_SIZE; k++) {
            float a0 = As[ty * 4][k];
            float a1 = As[ty * 4 + 1][k];
            float a2 = As[ty * 4 + 2][k];
            float a3 = As[ty * 4 + 3][k];

            float b0 = Bs[tx * 4][k];
            float b1 = Bs[tx * 4 + 1][k];
            float b2 = Bs[tx * 4 + 2][k];
            float b3 = Bs[tx * 4 + 3][k];

            // Unroll inner loop for better performance
            c[0][0] += a0 * b0;
            c[0][1] += a0 * b1;
            c[0][2] += a0 * b2;
            c[0][3] += a0 * b3;

            c[1][0] += a1 * b0;
            c[1][1] += a1 * b1;
            c[1][2] += a1 * b2;
            c[1][3] += a1 * b3;

            c[2][0] += a2 * b0;
            c[2][1] += a2 * b1;
            c[2][2] += a2 * b2;
            c[2][3] += a2 * b3;

            c[3][0] += a3 * b0;
            c[3][1] += a3 * b1;
            c[3][2] += a3 * b2;
            c[3][3] += a3 * b3;
        }

        __syncthreads();
    }

    // Write 4x4 block to global memory
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            int row = by + ty * 4 + i;
            int col = bx + tx * 4 + j;
            if (row < n && col < n) {
                C[row * n + col] = c[i][j];
            }
        }
    }
}

torch::Tensor matmul_forward_cuda(torch::Tensor A, torch::Tensor B) {
    int n = A.size(0);
    auto C = torch::zeros_like(A);

    dim3 threadsPerBlock(BLOCK_SIZE, BLOCK_SIZE);
    dim3 numBlocks((n + TILE_SIZE - 1) / TILE_SIZE, 
                   (n + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                 B.data_ptr<float>(), 
                                                 C.data_ptr<float>(), 
                                                 n);
    return C;
}
"""

